<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Personal Expense Tracker</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            background-color: #f5f5f5;
            padding: 20px;
            line-height: 1.6;
        }

        .container {
            max-width: 900px;
            margin: 0 auto;
            background: white;
            padding: 30px;
            border-radius: 8px;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
        }

        h1 {
            color: #333;
            margin-bottom: 30px;
            font-size: 28px;
        }

        .form-section {
            background-color: #f9f9f9;
            padding: 20px;
            border-radius: 6px;
            margin-bottom: 30px;
            border: 1px solid #e0e0e0;
        }

        .form-group {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 15px;
            margin-bottom: 15px;
        }

        .form-field {
            display: flex;
            flex-direction: column;
        }

        label {
            font-weight: 600;
            color: #555;
            margin-bottom: 5px;
            font-size: 14px;
        }

        input, select, textarea {
            padding: 10px;
            border: 1px solid #ddd;
            border-radius: 4px;
            font-size: 14px;
            font-family: inherit;
        }

        input:focus, select:focus, textarea:focus {
            outline: none;
            border-color: #4CAF50;
            background-color: #fafafa;
        }

        textarea {
            resize: vertical;
            min-height: 60px;
        }

        #add-expense {
            padding: 12px 24px;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 4px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: background-color 0.2s;
            align-self: flex-start;
        }

        #add-expense:hover {
            background-color: #45a049;
        }

        #add-expense:active {
            background-color: #3d8b40;
        }

        #form-error {
            color: #d32f2f;
            font-weight: 600;
            margin-bottom: 15px;
            padding: 10px;
            background-color: #ffebee;
            border-left: 4px solid #d32f2f;
            border-radius: 2px;
            min-height: 0;
            overflow: hidden;
            transition: all 0.2s;
        }

        #form-error:empty {
            display: none;
        }

        .filter-section {
            background-color: #f9f9f9;
            padding: 20px;
            border-radius: 6px;
            margin-bottom: 30px;
            border: 1px solid #e0e0e0;
        }

        .filter-group {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 15px;
        }

        .summary-section {
            background-color: #e8f5e9;
            padding: 20px;
            border-radius: 6px;
            margin-bottom: 30px;
            border: 1px solid #c8e6c9;
        }

        .summary-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            gap: 15px;
        }

        .summary-item {
            background: white;
            padding: 15px;
            border-radius: 4px;
            text-align: center;
            border: 1px solid #c8e6c9;
        }

        .summary-label {
            font-size: 12px;
            color: #666;
            font-weight: 600;
            text-transform: uppercase;
            margin-bottom: 5px;
        }

        .summary-amount {
            font-size: 24px;
            color: #2e7d32;
            font-weight: 700;
        }

        .expenses-section {
            margin-top: 30px;
        }

        .expenses-header {
            font-size: 18px;
            font-weight: 600;
            color: #333;
            margin-bottom: 15px;
        }

        .expense-list {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .expense {
            display: grid;
            grid-template-columns: 80px 100px 100px 1fr 80px;
            gap: 15px;
            align-items: center;
            padding: 15px;
            background-color: #fafafa;
            border-left: 4px solid #4CAF50;
            border-radius: 4px;
            border: 1px solid #e0e0e0;
        }

        .expense-amount {
            font-weight: 700;
            color: #2e7d32;
            font-size: 16px;
        }

        .expense-category {
            background-color: #e0e0e0;
            padding: 4px 8px;
            border-radius: 3px;
            font-size: 12px;
            font-weight: 600;
            color: #555;
            text-align: center;
        }

        .expense-date {
            font-size: 13px;
            color: #777;
        }

        .expense-note {
            font-size: 13px;
            color: #999;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .exp-del {
            padding: 8px 12px;
            background-color: #f44336;
            color: white;
            border: none;
            border-radius: 4px;
            font-size: 12px;
            font-weight: 600;
            cursor: pointer;
            transition: background-color 0.2s;
        }

        .exp-del:hover {
            background-color: #da190b;
        }

        .exp-del:active {
            background-color: #ba0000;
        }

        .empty-message {
            text-align: center;
            padding: 40px 20px;
            color: #999;
            font-style: italic;
        }

        @media (max-width: 768px) {
            .expense {
                grid-template-columns: 1fr;
                gap: 8px;
            }

            .expense-amount {
                font-size: 18px;
            }

            .form-group {
                grid-template-columns: 1fr;
            }

            .filter-group {
                grid-template-columns: 1fr;
            }

            .summary-content {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>💰 Personal Expense Tracker</h1>

        <div class="form-section">
            <div id="form-error"></div>
            <form id="expense-form">
                <div class="form-group">
                    <div class="form-field">
                        <label for="amount">Amount ($)</label>
                        <input type="number" id="amount" step="0.01" placeholder="0.00">
                    </div>
                    <div class="form-field">
                        <label for="category">Category</label>
                        <select id="category">
                            <option value="groceries">Groceries</option>
                            <option value="transport">Transport</option>
                            <option value="bills">Bills</option>
                            <option value="fun">Fun</option>
                        </select>
                    </div>
                    <div class="form-field">
                        <label for="date">Date</label>
                        <input type="date" id="date">
                    </div>
                    <div class="form-field">
                        <label for="note">Note (optional)</label>
                        <input type="text" id="note" placeholder="Add a note...">
                    </div>
                </div>
                <div class="form-field">
                    <label for="note">&nbsp;</label>
                    <button type="submit" id="add-expense">Add Expense</button>
                </div>
            </form>
        </div>

        <div class="filter-section">
            <h3 style="margin-bottom: 15px; color: #333; font-size: 16px;">Filters</h3>
            <div class="filter-group">
                <div class="form-field">
                    <label for="filter-category">Category</label>
                    <select id="filter-category">
                        <option value="all">All Categories</option>
                        <option value="groceries">Groceries</option>
                        <option value="transport">Transport</option>
                        <option value="bills">Bills</option>
                        <option value="fun">Fun</option>
                    </select>
                </div>
                <div class="form-field">
                    <label for="filter-from">From Date</label>
                    <input type="date" id="filter-from">
                </div>
                <div class="form-field">
                    <label for="filter-to">To Date</label>
                    <input type="date" id="filter-to">
                </div>
            </div>
        </div>

        <div class="summary-section">
            <div class="summary-content">
                <div class="summary-item">
                    <div class="summary-label">Total</div>
                    <div class="summary-amount" id="total">0.00</div>
                </div>
                <div class="summary-item">
                    <div class="summary-label">Groceries</div>
                    <div class="summary-amount cat-total" data-cat="groceries">0.00</div>
                </div>
                <div class="summary-item">
                    <div class="summary-label">Transport</div>
                    <div class="summary-amount cat-total" data-cat="transport">0.00</div>
                </div>
                <div class="summary-item">
                    <div class="summary-label">Bills</div>
                    <div class="summary-amount cat-total" data-cat="bills">0.00</div>
                </div>
                <div class="summary-item">
                    <div class="summary-label">Fun</div>
                    <div class="summary-amount cat-total" data-cat="fun">0.00</div>
                </div>
            </div>
        </div>

        <div class="expenses-section">
            <div class="expenses-header">Expenses</div>
            <div class="expense-list" id="expense-list"></div>
        </div>
    </div>

    <script>
        // State
        let expenses = [];

        // DOM Elements
        const amountInput = document.getElementById('amount');
        const categoryInput = document.getElementById('category');
        const dateInput = document.getElementById('date');
        const noteInput = document.getElementById('note');
        const addExpenseBtn = document.getElementById('add-expense');
        const formError = document.getElementById('form-error');
        const expenseForm = document.getElementById('expense-form');
        const expenseList = document.getElementById('expense-list');
        const totalElement = document.getElementById('total');
        const filterCategoryInput = document.getElementById('filter-category');
        const filterFromInput = document.getElementById('filter-from');
        const filterToInput = document.getElementById('filter-to');

        // Initialize
        function init() {
            loadExpenses();
            setDateToToday();
            render();

            // Event listeners
            expenseForm.addEventListener('submit', handleAddExpense);
            filterCategoryInput.addEventListener('change', render);
            filterFromInput.addEventListener('change', render);
            filterToInput.addEventListener('change', render);
        }

        function setDateToToday() {
            const today = new Date().toISOString().split('T')[0];
            dateInput.value = today;
        }

        function loadExpenses() {
            const stored = localStorage.getItem('expenses');
            if (stored) {
                try {
                    expenses = JSON.parse(stored);
                } catch (e) {
                    expenses = [];
                }
            }
        }

        function saveExpenses() {
            localStorage.setItem('expenses', JSON.stringify(expenses));
        }

        function handleAddExpense(e) {
            e.preventDefault();

            // Clear error
            formError.textContent = '';

            // Validate
            const amount = parseFloat(amountInput.value);
            const date = dateInput.value;

            if (!amountInput.value || isNaN(amount) || amount <= 0) {
                formError.textContent = 'Please enter a valid amount (must be greater than 0).';
                return;
            }

            if (!date) {
                formError.textContent = 'Please select a date.';
                return;
            }

            // Create expense
            const expense = {
                id: Date.now(),
                amount: amount,
                category: categoryInput.value,
                date: date,
                note: noteInput.value
            };

            // Add to list
            expenses.unshift(expense);
            saveExpenses();

            // Reset form
            amountInput.value = '';
            noteInput.value = '';
            setDateToToday();

            // Re-render
            render();
        }

        function deleteExpense(id) {
            expenses = expenses.filter(exp => exp.id !== id);
            saveExpenses();
            render();
        }

        function getVisibleExpenses() {
            const categoryFilter = filterCategoryInput.value;
            const fromFilter = filterFromInput.value;
            const toFilter = filterToInput.value;

            return expenses.filter(expense => {
                // Category filter
                if (categoryFilter !== 'all' && expense.category !== categoryFilter) {
                    return false;
                }

                // Date filters
                if (fromFilter && expense.date < fromFilter) {
                    return false;
                }

                if (toFilter && expense.date > toFilter) {
                    return false;
                }

                return true;
            });
        }

        function render() {
            renderExpenses();
            updateSummary();
        }

        function renderExpenses() {
            const visible = getVisibleExpenses();

            if (visible.length === 0) {
                expenseList.innerHTML = '<div class="empty-message">No expenses yet. Add one to get started!</div>';
                return;
            }

            expenseList.innerHTML = visible.map(expense => {
                return `
                    <div class="expense">
                        <div class="expense-amount">$${expense.amount.toFixed(2)}</div>
                        <div class="expense-category">${capitalize(expense.category)}</div>
                        <div class="expense-date">${formatDate(expense.date)}</div>
                        <div class="expense-note">${expense.note || '-'}</div>
                        <button class="exp-del" onclick="deleteExpense(${expense.id})">Delete</button>
                    </div>
                `;
            }).join('');
        }

        function updateSummary() {
            const visible = getVisibleExpenses();

            // Calculate total
            const total = visible.reduce((sum, exp) => sum + exp.amount, 0);
            totalElement.textContent = total.toFixed(2);

            // Calculate per-category totals
            const categories = ['groceries', 'transport', 'bills', 'fun'];
            categories.forEach(cat => {
                const catTotal = visible
                    .filter(exp => exp.category === cat)
                    .reduce((sum, exp) => sum + exp.amount, 0);

                const catElement = document.querySelector(`.cat-total[data-cat="${cat}"]`);
                if (catElement) {
                    catElement.textContent = catTotal.toFixed(2);
                }
            });
        }

        function capitalize(str) {
            return str.charAt(0).toUpperCase() + str.slice(1);
        }

        function formatDate(dateString) {
            const date = new Date(dateString + 'T00:00:00');
            return date.toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'short',
                day: 'numeric'
            });
        }

        // Start app
        init();
    </script>
</body>
</html>
